# Advanced Build Script Template
# Customize this for your specific project needs

param(
    [Parameter(Mandatory=$false)]
    [ValidateSet('Debug', 'Release')]
    [string]$Configuration = 'Release',

    [Parameter(Mandatory=$false)]
    [switch]$Clean,

    [Parameter(Mandatory=$false)]
    [switch]$Test,

    [Parameter(Mandatory=$false)]
    [string]$Version,

    [Parameter(Mandatory=$false)]
    [switch]$Sign,

    [Parameter(Mandatory=$false)]
    [string]$CertificatePath
)

$ErrorActionPreference = "Stop"

# Configuration
$ProjectName = "YourAppName"
$EntryPoint = "src/main.py"
$IconPath = "assets/icon.ico"

# Colors for output
function Write-Info { param($msg) Write-Host $msg -ForegroundColor Cyan }
function Write-Success { param($msg) Write-Host $msg -ForegroundColor Green }
function Write-Error { param($msg) Write-Host $msg -ForegroundColor Red }
function Write-Warning { param($msg) Write-Host $msg -ForegroundColor Yellow }

Write-Info "Building $ProjectName ($Configuration)"
Write-Info ("=" * 50)

# Clean previous builds
if ($Clean) {
    Write-Info "Cleaning build artifacts..."
    Remove-Item -Recurse -Force build, dist -ErrorAction SilentlyContinue
    Write-Success "Clean complete"
}

# Install dependencies
Write-Info "Installing dependencies..."
pip install -r requirements.txt --quiet
if ($LASTEXITCODE -ne 0) {
    Write-Error "Failed to install dependencies"
    exit 1
}

# Run tests if requested
if ($Test) {
    Write-Info "Running tests..."
    python -m pytest tests/
    if ($LASTEXITCODE -ne 0) {
        Write-Error "Tests failed!"
        exit 1
    }
    Write-Success "Tests passed"
}

# Update version if provided
if ($Version) {
    Write-Info "Setting version to $Version"
    # Update version in your code here
    # Example: (Get-Content src/__init__.py) -replace '__version__ = ".*"', "__version__ = `"$Version`"" | Set-Content src/__init__.py
}

# Build PyInstaller arguments
$PyInstallerArgs = @(
    "--name=$ProjectName",
    "--clean",
    $EntryPoint
)

if ($Configuration -eq "Release") {
    $PyInstallerArgs += "--windowed"  # No console window
    $PyInstallerArgs += "--onefile"    # Single executable
} else {
    $PyInstallerArgs += "--console"    # Show console for debugging
    $PyInstallerArgs += "--debug=all"  # Debug mode
}

if (Test-Path $IconPath) {
    $PyInstallerArgs += "--icon=$IconPath"
}

# Add any additional data files
# $PyInstallerArgs += "--add-data", "config.json;."
# $PyInstallerArgs += "--add-data", "assets;assets"

# Add hidden imports if needed
# $PyInstallerArgs += "--hidden-import=module_name"

# Build executable
Write-Info "Building executable..."
pyinstaller @PyInstallerArgs

if ($LASTEXITCODE -ne 0) {
    Write-Error "Build failed!"
    exit 1
}

# Sign executable if requested
if ($Sign) {
    Write-Info "Signing executable..."
    if (-not $CertificatePath) {
        Write-Error "Certificate path required for signing (use -CertificatePath)"
        exit 1
    }

    $exePath = "dist\$ProjectName.exe"
    if (Test-Path $exePath) {
        # Note: Requires signtool.exe (from Windows SDK)
        # signtool sign /f $CertificatePath /p $CertPassword /t http://timestamp.digicert.com $exePath
        Write-Warning "Signing not implemented - add your signing logic here"
    }
}

# Calculate file size
$exePath = "dist\$ProjectName.exe"
if (Test-Path $exePath) {
    $fileSize = (Get-Item $exePath).Length / 1MB
    Write-Success ("`nBuild successful!")
    Write-Success ("Executable: $exePath")
    Write-Success ("Size: {0:N2} MB" -f $fileSize)

    if ($fileSize -gt 50) {
        Write-Warning "Executable is quite large. Consider:"
        Write-Warning "  - Using --onedir instead of --onefile"
        Write-Warning "  - Excluding unused modules with --exclude-module"
        Write-Warning "  - Using a virtual environment with only required packages"
    }
} else {
    Write-Error "Executable not found!"
    exit 1
}

Write-Info ("`n" + ("=" * 50))
Write-Info "Build complete!"

